#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <functional>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> ev(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> ev[i][j];
        }
    }

    sort(ev.begin(), ev.end());
    priority_queue<long long, vector<long long>, greater<long long>> heap;
    long long i = 0, day = 0, count = 0;
    while (i < n || !heap.empty()) {
        if (heap.empty()) day = max(day, ev[i][0]);
        while (i < n && ev[i][0] <= day) {
            heap.push(ev[i][1]);
            i++;
        }
        while (!heap.empty() && heap.top() < day) heap.pop();
        if (!heap.empty()) {
            heap.pop();
            count++;
            day++;
        }
    }
    cout << count << "\n";

    return 0;
}

