import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long[] heap;
    static int heapSize;

    static void heapPush(long v) {
        int i = heapSize++;
        heap[i] = v;
        while (i > 0) {
            int p = (i - 1) / 2;
            if (heap[p] <= heap[i]) break;
            long t = heap[p];
            heap[p] = heap[i];
            heap[i] = t;
            i = p;
        }
    }

    static long heapPop() {
        long top = heap[0];
        heapSize--;
        if (heapSize > 0) {
            heap[0] = heap[heapSize];
            int i = 0;
            while (true) {
                int l = 2 * i + 1, rr = l + 1, m = i;
                if (l < heapSize && heap[l] < heap[m]) m = l;
                if (rr < heapSize && heap[rr] < heap[m]) m = rr;
                if (m == i) break;
                long t = heap[m];
                heap[m] = heap[i];
                heap[i] = t;
                i = m;
            }
        }
        return top;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] ev = new long[(int) n][2];
        for (int i = 0; i < ev.length; i++) {
            for (int j = 0; j < ev[i].length; j++) {
                ev[i][j] = Long.parseLong(next());
            }
        }

        int cnt = (int) n;
        long[] keys = new long[cnt];
        for (int t = 0; t < cnt; t++) keys[t] = (ev[t][0] << 30) | ev[t][1];
        Arrays.sort(keys);
        long mask = (1L << 30) - 1;
        heap = new long[cnt + 5];
        heapSize = 0;
        int i = 0;
        long day = 0, count = 0;
        while (i < cnt || heapSize > 0) {
            if (heapSize == 0) day = Math.max(day, keys[i] >> 30);
            while (i < cnt && (keys[i] >> 30) <= day) {
                heapPush(keys[i] & mask);
                i++;
            }
            while (heapSize > 0 && heap[0] < day) heapPop();
            if (heapSize > 0) {
                heapPop();
                count++;
                day++;
            }
        }
        System.out.println(count);
    }
}
